#pragma once

// Ed25519 public-key generation (RFC 8032 section 5.1.5), for key-fingerprint
// tags (spec 02 section 6), and the X25519 public key (RFC 7748) for pairing. The
// sensor never signs, so only multiples of the base point are here.
//
// Provenance: the point formulas, signed radix-16 recoding and constant-time table
// selection of ref10 (Bernstein, Duif, Lange, Schwabe, Yang; public domain, SUPERCOP
// crypto_sign/ed25519/ref10), on the field code in cs_fe25519.h. The comb table is
// generated by tests/sensor_core/gen_ed25519_table.py. Constant time: no branches or
// indices on secrets.

#include <cstdint>

#include "cs_fe25519.h"

namespace esphome::cs_sensor {

// pub = the Ed25519 public key for the 32-byte private key (seed), all at once.
void cs_ed25519_public_key(const uint8_t seed[32], uint8_t pub[32]);

// One multiplication of the base point B by a secret scalar, in bounded steps, so a
// caller can spread it across loop passes. It gives an Ed25519 public key, or
// an X25519 one through the map u = (1 + y) / (1 - y), which takes B to the X25519
// base point u = 9 (RFC 7748 section 4.1). Both clamp their scalar the same way.
//
// A step costs at most about eight field multiplications. The sequence of steps
// is the same for every scalar, so where the caller splits it reveals nothing.
class BaseMulJob {
 public:
  ~BaseMulJob() { this->clear(); }
  void start_ed25519(const uint8_t seed[32]);
  void start_x25519(const uint8_t scalar[32]);
  // Runs one step; true once result() holds the public key.
  bool step();
  bool busy() const { return this->stage_ != Stage::IDLE && this->stage_ != Stage::DONE; }
  bool done() const { return this->stage_ == Stage::DONE; }
  const uint8_t *result() const { return this->out_; }
  // Wipes every secret and the result, and goes idle.
  void clear();

  struct P3 {
    fe25519::fe X, Y, Z, T;  // extended coordinates: x = X/Z, y = Y/Z, xy = T/Z
  };

 private:
  enum class Stage : uint8_t { IDLE, PREPARE, COMB, INVERT, FINISH, DONE };
  void prepare_();

  Stage stage_{Stage::IDLE};
  bool x25519_{false};
  uint8_t scalar_[32]{};  // the seed, then the clamped scalar
  int8_t e_[64]{};        // signed radix-16 digits of the scalar, in [-8, 8]
  uint8_t sweep_{0};      // comb pass, counting down
  uint8_t table_{0};      // next table in the pass
  uint8_t doublings_{0};  // still to do before the pass
  P3 h_{};
  fe25519::Inverter inv_{};
  uint8_t out_[32]{};
};

}  // namespace esphome::cs_sensor
